/* 115200 8N1，收发双向 */
UART_HandleTypeDef huart1;

huart1.Instance          = USART1;
huart1.Init.BaudRate     = 115200;
huart1.Init.WordLength   = UART_WORDLENGTH_8B;
huart1.Init.StopBits     = UART_STOPBITS_1;
huart1.Init.Parity       = UART_PARITY_NONE;
huart1.Init.Mode         = UART_MODE_TX_RX;
huart1.Init.HwFlowCtl    = UART_HWCONTROL_NONE;
huart1.Init.OverSampling = UART_OVERSAMPLING_16;
if (HAL_UART_Init(&huart1) != HAL_OK)
{
  Error_Handler();
}

uint8_t msg[] = "Hello STM32\r\n";

/* 阻塞发送：函数返回时数据已全部写入发送寄存器 */
HAL_UART_Transmit(&huart1, msg, sizeof(msg) - 1, HAL_MAX_DELAY);

/* 注意 Size 是字节数，不含结尾的 '\0'，所以减 1 */

uint8_t buf[] = "IT mode\r\n";

/* 非阻塞：函数立刻返回，发完进 TxCpltCallback */
HAL_UART_Transmit_IT(&huart1, buf, sizeof(buf) - 1);

void HAL_UART_TxCpltCallback(UART_HandleTypeDef *huart)
{
  /* 发送完成，可以启动下一批 */
}

uint8_t rx_byte;

/* 开一次接收中断（收满 1 字节触发回调） */
HAL_UART_Receive_IT(&huart1, &rx_byte, 1);

/* 回调里必须再次调用，否则只能收到第一字节 */
void HAL_UART_RxCpltCallback(UART_HandleTypeDef *huart)
{
  if (huart->Instance == USART1)
  {
    /* 处理 rx_byte */
    HAL_UART_Receive_IT(&huart1, &rx_byte, 1);
  }
}

/* 不定长接收：DMA + 空闲中断，最省心的写法 */
uint8_t rx_buf[128];

HAL_UARTEx_ReceiveToIdle_DMA(&huart1, rx_buf, sizeof(rx_buf));

void HAL_UARTEx_RxEventCallback(UART_HandleTypeDef *huart, uint16_t Size)
{
  if (huart->Instance == USART1)
  {
    /* Size 是本帧实际收到的字节数 */
    Handle_Frame(rx_buf, Size);
    HAL_UARTEx_ReceiveToIdle_DMA(&huart1, rx_buf, sizeof(rx_buf));
  }
}
